38	/// Per-content-block state keyed by `content_block_index`.
39	///
40	/// Reasoning content blocks are identified purely by the
41	/// `ContentBlockDelta::ReasoningContent` delta variant; no separate block-state
42	/// entry is needed for them.
43	#[derive(Debug)]
44	enum BlockState {
45	    Text,
46	    ToolUse {
47	        call_id: String,
48	        name: String,
49	        /// `true` after the first `ToolCallDelta` has been emitted (name
50	        /// appears only in that first delta; subsequent deltas set it to
51	        /// `None`).
52	        name_emitted: bool,
53	    },
54	}
55	
56	// ── public translator ─────────────────────────────────────────────────────────
57	
58	/// State machine that maps Bedrock `ConverseStreamOutput` events to
59	/// `paigasus_helikon_core::ModelEvent`s.
60	///
61	/// Call [`StreamTranslator::consume`] once per SDK event.  The translator is
62	/// pure (no I/O) and is intended to be driven from an `async_stream!` wrapper
63	/// that feeds it chunks from `converse_stream`.
64	///
65	/// ## Synthesizing mode
66	///
67	/// When `synthesizing = true` the model was asked to fill a JSON schema via a
68	/// forced-tool call (`__paigasus_structured_output__`).  In that mode the
69	/// synthesized tool's input deltas are re-emitted as `TokenDelta`s and the
70	/// terminal `tool_use` stop reason is rewritten to `Stop`.  If a *real* tool
71	/// fires alongside the synthesized one, `ModelError::Other` is returned
72	/// (protocol violation).
73	#[derive(Debug, Default)]
74	pub struct StreamTranslator {
75	    /// `content_block_index` → per-block state.
76	    blocks: HashMap<i32, BlockState>,
77	    /// Whether we are in structured-output synthesis mode.
78	    synthesizing: bool,
79	    /// Whether the request used native structured output (`outputConfig`).
80	    native: bool,
81	    /// Whether the request set `tool_choice` to `None`. A tool call is then an error.
82	    forbid_tool_calls: bool,
83	    /// `true` once a refused tool call produced its error.
84	    refused_tool_call: bool,
85	    /// The content-block index of the synthesized tool's block (if any).
86	    synthesized_block_index: Option<i32>,
87	    /// `true` if at least one *real* (non-synthesized) tool block started.
88	    real_tool_fired: bool,
89	    /// Buffered stop reason from `MessageStop`; held until `Metadata` arrives
90	    /// so that `Usage` can be emitted first.
91	    pending_stop_reason: Option<StopReason>,
92	    /// `true` once a `Metadata` event has been processed.
93	    metadata_seen: bool,
94	    /// `true` once a terminal event (`Finish` or an `Err`) was produced.
95	    // Read by the ContentBlockStop arm (SMA-863 Task 5).
96	    terminal_emitted: bool,
97	}
98	
99	impl StreamTranslator {
100	    /// Create a new translator.
101	    ///
102	    /// Set `synthesizing` to `true` when the request was built with
103	    /// structured-output synthesis (forced `__paigasus_structured_output__`
104	    /// tool call).
105	    pub fn new(synthesizing: bool) -> Self {
106	        Self {
107	            synthesizing,
108	            ..Default::default()
109	        }
110	    }
111	
112	    /// Tell the translator that the request used native structured output.
113	    /// An anchor call then logs one warning, because `outputConfig` did not
114	    /// constrain the text that the anchor carries.
115	    pub(crate) fn native(mut self, native: bool) -> Self {
116	        self.native = native;
117	        self
118	    }
119	
120	    /// Tell the translator that the request set `tool_choice` to `None`.
121	    /// A tool call from the model then becomes an error.
122	    pub(crate) fn forbid_tool_calls(mut self, forbid: bool) -> Self {
123	        self.forbid_tool_calls = forbid;
124	        self
125	    }
126	
127	    /// Consume one `ConverseStreamOutput` event and return zero or more
128	    /// `ModelEvent`s (or `ModelError`s) produced by it.
129	    pub fn consume(&mut self, ev: ConverseStreamOutput) -> Vec<Result<ModelEvent, ModelError>> {
130	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
131	
132	        match ev {
133	            // ── events that produce no output ─────────────────────────────────
134	            ConverseStreamOutput::MessageStart(_) => {}
135	            ConverseStreamOutput::ContentBlockStop(_) => {}
136	
137	            // ── content block start ───────────────────────────────────────────
138	            ConverseStreamOutput::ContentBlockStart(e) => {
139	                let idx = e.content_block_index();
140	                match e.start() {
141	                    Some(ContentBlockStart::ToolUse(tu)) => {
142	                        let call_id = tu.tool_use_id().to_owned();
143	                        let name = tu.name().to_owned();
144	
145	                        if self.synthesizing && name == SYNTHESIZED_TOOL_NAME {
146	                            if self.native && self.synthesized_block_index.is_none() {
147	                                tracing::warn!(
148	                                    target: "paigasus::bedrock::stream",
149	                                    "the model called the structured-output anchor on the native path; outputConfig did not constrain this text"
150	                                );
151	                            }
152	                            self.synthesized_block_index = Some(idx);
153	                        } else if self.forbid_tool_calls {
154	                            // Record no block: its deltas then emit nothing.
155	                            // A second refused block at another index is
156	                            // silent: the error is emitted once per stream.
157	                            if !self.refused_tool_call {
158	                                self.refused_tool_call = true;
159	                                self.terminal_emitted = true;
160	                                out.push(Err(ModelError::Other(anyhow::anyhow!(
161	                                    "the model called a tool, but tool_choice is None"
162	                                ))));
163	                            }
164	                            return out;
165	                        } else {
166	                            self.real_tool_fired = true;
167	                            // Emit the name-carrying delta immediately on block
168	                            // start (mirrors the Anthropic provider's behaviour
169	                            // of emitting name on the first input-json delta).
170	                            // We *don't* emit here — we wait for the first
171	                            // tool-input delta so the call_id→state map is
172	                            // consistent.
173	                        }
174	                        self.blocks.insert(
175	                            idx,
176	                            BlockState::ToolUse {
177	                                call_id,
178	                                name,
179	                                name_emitted: false,
180	                            },
181	                        );
182	                    }
183	                    Some(ContentBlockStart::Image(_) | ContentBlockStart::ToolResult(_)) => {
184	                        // Not a tool we translate; record nothing.
185	                    }
186	                    Some(_) | None => {
187	                        // Text or unknown start: record as text block.
188	                        self.blocks.insert(idx, BlockState::Text);
189	                    }
190	                }
191	            }
192	
193	            // ── content block delta ───────────────────────────────────────────
194	            ConverseStreamOutput::ContentBlockDelta(e) => {
195	                let idx = e.content_block_index();
196	                match e.delta() {
197	                    Some(ContentBlockDelta::Text(text)) => {
198	                        out.push(Ok(ModelEvent::TokenDelta { text: text.clone() }));
199	                    }
200	                    Some(ContentBlockDelta::ToolUse(tu_delta)) => {
201	                        let input = tu_delta.input().to_owned();
202	                        let is_synth = Some(idx) == self.synthesized_block_index;
203	
204	                        if is_synth {
205	                            // Remap synthesized tool input to TokenDelta.
206	                            out.push(Ok(ModelEvent::TokenDelta { text: input }));
207	                        } else if let Some(BlockState::ToolUse {
208	                            call_id,
209	                            name,
210	                            name_emitted,
211	                        }) = self.blocks.get_mut(&idx)
212	                        {
213	                            let emit_name = if *name_emitted {
214	                                None
215	                            } else {
216	                                *name_emitted = true;
217	                                Some(name.clone())
218	                            };
219	                            out.push(Ok(ModelEvent::ToolCallDelta {
220	                                call_id: call_id.clone(),
221	                                name: emit_name,
222	                                args_delta: input,
223	                            }));
224	                        }
225	                        // If no block state (shouldn't happen for well-formed
226	                        // streams), silently drop rather than panic.
227	                    }
228	                    Some(ContentBlockDelta::ReasoningContent(rc)) => match rc {
229	                        ReasoningContentBlockDelta::Text(text) => {
230	                            out.push(Ok(ModelEvent::ReasoningDelta { text: text.clone() }));
231	                        }
232	                        ReasoningContentBlockDelta::Signature(_) => {
233	                            // Signature is a round-trip token for multi-turn
234	                            // extended-thinking; we drop it here (not yet
235	                            // plumbed through the session layer).
236	                            tracing::debug!(
237	                                target: "paigasus::bedrock::stream",
238	                                "reasoning signature delta dropped (round-trip not yet supported)",
239	                            );
240	                        }
241	                        ReasoningContentBlockDelta::RedactedContent(_) => {
242	                            // Encrypted reasoning blob — provider-opaque, drop.
243	                            tracing::debug!(
244	                                target: "paigasus::bedrock::stream",
245	                                "reasoning redacted-content delta dropped",
246	                            );
247	                        }
248	                        _ => {
249	                            // Forward-compat: ignore unknown reasoning variants.
250	                        }
251	                    },
252	                    // Image, ToolResult, Citation, Unknown deltas — drop.
253	                    Some(_) | None => {}
254	                }
255	            }
256	
257	            // ── message stop (stop_reason) ────────────────────────────────────
258	            ConverseStreamOutput::MessageStop(e) => {
259	                let stop_reason = e.stop_reason().clone();
260	                if self.metadata_seen {
261	                    // Metadata already arrived; emit Finish now.
262	                    out.extend(self.finish_events(stop_reason));
263	                } else {
264	                    // Buffer; Metadata will trigger Usage + Finish.
265	                    self.pending_stop_reason = Some(stop_reason);
266	                }
267	            }
268	
269	            // ── metadata (usage) ──────────────────────────────────────────────
270	            ConverseStreamOutput::Metadata(e) => {
271	                self.metadata_seen = true;
272	                if let Some(usage) = e.usage() {
273	                    out.push(Ok(ModelEvent::Usage {
274	                        input_tokens: usage.input_tokens().max(0) as u32,
275	                        output_tokens: usage.output_tokens().max(0) as u32,
276	                        cached_input_tokens: usage
277	                            .cache_read_input_tokens()
278	                            .map(|n| n.max(0) as u32),
279	                        reasoning_tokens: None,
280	                    }));
281	                }
282	                // If a buffered stop reason is waiting, emit Finish now.
283	                if let Some(reason) = self.pending_stop_reason.take() {
284	                    out.extend(self.finish_events(reason));
285	                }
286	            }
287	
288	            // Forward-compat catch-all: Unknown and any future enum variants
289	            // added by the SDK are silently ignored.
290	            _ => {}
291	        }
292	
293	        out
294	    }
295	
296	    /// Flush any buffered stop reason when the Bedrock stream ends normally
297	    /// (EOF) without having emitted a `Metadata` event.
298	    ///
299	    /// Returns the terminal `Finish` event (or a `ModelError::Other` for the
300	    /// both-tools-fired error condition) if a stop reason is still pending.
301	    /// Returns an empty `Vec` if the stream already emitted its terminal event
302	    /// through the normal `Metadata`→`Finish` path.
303	    ///
304	    /// **Call this only on the EOF path, not on the cancellation path.**
305	    /// Cancellation must end the stream without emitting `Finish`.
306	    pub(crate) fn finish(&mut self) -> Vec<Result<ModelEvent, ModelError>> {
307	        match self.pending_stop_reason.take() {
308	            Some(reason) => self.finish_events(reason),
309	            None => Vec::new(),
310	        }
311	    }
312	
313	    // ── private helpers ───────────────────────────────────────────────────────
314	
315	    /// Translate a `StopReason` into the terminal event(s).
316	    ///
317	    /// Returns a single `Ok(Finish{..})` in normal cases, or a single
318	    /// `Err(ModelError::Other)` when both a real and the synthesized tool
319	    /// fired in synthesis mode.
320	    fn finish_events(&mut self, reason: StopReason) -> Vec<Result<ModelEvent, ModelError>> {
321	        // A refused tool call already ended the stream with an error. As on the
322	        // both-tools-fired path, the error replaces the terminal `Finish`.
323	        if self.refused_tool_call {
324	            return Vec::new();
325	        }
326	        let finish = match reason {
327	            StopReason::EndTurn | StopReason::StopSequence => Ok(ModelEvent::Finish {
328	                reason: FinishReason::Stop,
329	            }),
330	            StopReason::ToolUse => {
331	                if self.synthesizing {
332	                    if self.real_tool_fired {
333	                        // Both tools fired — protocol violation.
334	                        Err(ModelError::Other(anyhow::anyhow!(
335	                            "bedrock stream: structured-output synthesis: \
336	                             model fired both a real tool and the synthesized \
337	                             output tool '__paigasus_structured_output__'"
338	                        )))
339	                    } else {
340	                        // Only synthesized tool fired — rewrite to Stop.
341	                        Ok(ModelEvent::Finish {
342	                            reason: FinishReason::Stop,
343	                        })
344	                    }
345	                } else {
346	                    Ok(ModelEvent::Finish {
347	                        reason: FinishReason::ToolCalls,
348	                    })
349	                }
350	            }
351	            StopReason::MaxTokens => Ok(ModelEvent::Finish {
352	                reason: FinishReason::Length,
353	            }),
